import { GetObjectCommand, PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";

const s3 = new S3Client({ forcePathStyle: true }); // endpoint and keys come from the AWS_* env vars
const runId = "run-42";
const name = process.argv[2] ?? "notes.md";
const params = { Bucket: "rhino-ai-agents-runs", Key: `runs/${runId}/${name}` };

const put = await getSignedUrl(s3, new PutObjectCommand(params), { expiresIn: 900 });
const get = await getSignedUrl(s3, new GetObjectCommand(params), { expiresIn: 900 });
console.log(`PUT=${put}`);
console.log(`GET=${get}`);
